insert into footy.season_player_evidence(
    claim_key, snapshot_id, club_id, player_id, external_player_id,
    player_label, evidence_type, evidence_date, appearances,
    source_id, source_url, raw_evidence, rights_basis, review_status
)
select r.claim_key, r.snapshot_id, r.club_id, null, r.external_player_id,
       r.player_label, r.evidence_type, null, null,
       r.source_id, r.source_url, r.raw_evidence, r.rights_basis, 'pending'
from incoming r
join footy.season_club_participants p on
    p.snapshot_id=r.snapshot_id and p.club_id=r.club_id
on conflict (claim_key) do nothing;
commit;

select count(*) as staged_arsenal_claims,
       count(*) filter (where raw_evidence->>'from_literal' is null) as undated,
       count(*) filter (where review_status='pending') as pending
from footy.season_player_evidence
where snapshot_id='epl_2026_27_prejan_20261104'
and club_id='club_arsenal';